def nested_raw(key, raw):
    # Indentation is the only envelope operation: no parsed output reserialization.
    return key + ':\n' + textwrap.indent(raw, '  ') + ('\n' if not raw.endswith('\n') else '')

def run_case(c, route, model):
    record={'name':c['name'],'fixture':c,'stages':[],'assertions':[],'pass':False,'execution_mode':'authorized chain' if c['expected']['orchestrator']=='ready' else 'negative gate probe; no admitted downstream execution'}
    try:
        g=native('governor',yaml.safe_dump({'initiative':c['initiative']},sort_keys=False),route,model); record['stages'].append(g)
        validate_governor(g['parsed'],g['assertions']); check(g['parsed']['decision']==c['expected']['governor'],'Expected Governor decision',record['assertions'])
        oinput=yaml.safe_dump({'initiative':c['initiative']},sort_keys=False)+nested_raw('governance',g['raw_response'])+yaml.safe_dump({'available_realm_owners':c['owners'],'planning_room':{'contributions':c['contributions']}},sort_keys=False)
        check(textwrap.dedent(oinput.split('governance:\n',1)[1].split('available_realm_owners:',1)[0]).rstrip('\n')==g['raw_response'].rstrip('\n'),'Governor raw response passed unchanged (only YAML indentation/newline envelope)',record['assertions'])
        check(yaml.safe_load(oinput)['governance']==g['parsed'],'Governor semantic envelope equality',record['assertions'])
        o=native('orchestrator',oinput,route,model); record['stages'].append(o)
        validate_orchestrator(o['parsed'],{v['owner'] for v in c['owners']},o['assertions']); check(o['parsed']['orchestration_status']==c['expected']['orchestrator'],'Expected Orchestrator status',record['assertions'])
        s=o['parsed']['initiative_state']
        if g['parsed']['decision']!='proceed':
            check(all(not s[k] for k in ['work','decisions','assumptions','success_criteria','requested_contributions']) and s['scope']=={'in':[],'out':[]} and s['team']=={'lead_owner':None,'participating_owners':[]} and bool(s['blockers']),'Non-proceed governance refuses all planning',record['assertions'])
        if c['name']=='missing_specialist_evidence':
            check(s['requested_contributions'] and s['blockers'],'Missing facts request selected specialist evidence, not readiness',record['assertions'])
        if o['parsed']['orchestration_status']=='ready':
            targets=[w for w in s['work'] if w['owner']==OWNER and ('draft' in w['id'].lower() or 'sentence' in w['objective'].lower()) and ('version 3' not in w['objective'].lower()) and ('verify' not in w['id'].lower())]
            check(len(targets)==1,'Unambiguous actual returned assigned draft work',record['assertions'])
            target=targets[0]; deps=target['depends_on']
        else:
            target={'id':'draft_update'}; deps=[]
        assignment={'canonical_domain':'research_learning' if c['assignment_mode']=='wrong_domain' else 'professional_delivery','owner':'unassigned_owner' if c['assignment_mode']=='wrong_owner' else OWNER,'work_id':target['id']}
        dependency_evidence=[]
        if c['dependencies_mode']!='none':
            check(len(deps)==1,'Actual plan has exactly one direct drafting dependency',record['assertions'])
            if c['dependencies_mode']!='missing':
                if c['dependencies_mode']=='satisfied':
                    prerequisite_id=deps[0]
                    prerequisite=next(w for w in s['work'] if w['id']==prerequisite_id)
                    check(prerequisite['owner']==OWNER and not prerequisite['depends_on'], 'Actual prerequisite is independently assigned to this Owner', record['assertions'])
                    prerequisite_assignment={'canonical_domain':'professional_delivery','owner':OWNER,'work_id':prerequisite_id}
                    prerequisite_input=nested_raw('handoff',o['raw_response'])+yaml.safe_dump({'assignment':prerequisite_assignment,'dependencies':[],'approval_authority':'The requesting human; no approval or release.','context':BASE_FACT+' The assigned prerequisite is bounded textual inspection of this supplied record only. Check that it explicitly supplies version 2 and the search typo fix; return the inspection finding, not the dependent draft update. No external retrieval or external verification exists.'},sort_keys=False)
                    evidence_run=native('owner',prerequisite_input,route,model)
                    evidence_run['purpose']='actual assigned prerequisite text inspection'
                    record['stages'].append(evidence_run)
                    validate_owner(evidence_run['parsed'],prerequisite_assignment,evidence_run['assertions'])
                    check(evidence_run['parsed']['owner_status']=='review', 'Actual prerequisite inspection reaches REVIEW with checks', record['assertions'])
                    dependency_evidence=[{'id':prerequisite_id,'satisfied':True,'evidence':evidence_run['raw_response']}]
                    check(dependency_evidence[0]['evidence']==evidence_run['raw_response'],'Actual prerequisite response passed unchanged as dependency evidence',record['assertions'])
                else:
                    dependency_evidence=[{'id':dep,'satisfied':False,'evidence':''} for dep in deps]
        supplement={'assignment':assignment,'dependencies':dependency_evidence,'approval_authority':'The requesting human; this invocation grants no approval or release.','context':c['owner_context']}
        owner_input=nested_raw('handoff',o['raw_response'])+yaml.safe_dump(supplement,sort_keys=False)
        check(textwrap.dedent(owner_input.split('handoff:\n',1)[1].split('assignment:',1)[0]).rstrip('\n')==o['raw_response'].rstrip('\n'),'Orchestrator raw response passed unchanged (only YAML indentation/newline envelope)',record['assertions'])
        check(yaml.safe_load(owner_input)['handoff']==o['parsed'],'Orchestrator semantic envelope equality',record['assertions'])
        own=native('owner',owner_input,route,model); record['stages'].append(own)
        validate_owner(own['parsed'],assignment,own['assertions']); check(own['parsed']['owner_status'] in c['expected']['owner'],'Expected Owner status',record['assertions'])
        content=own['parsed']['result']['content']
        if content is not None:
            expected=['version 9','offline','export'] if c['name']=='isolation_beta' else ['version 2','search','typo']
            check(all(t in content.lower() for t in expected),'Assigned supplied-fact content only',record['assertions'])
            forbidden=['version 2','search','typo'] if c['name']=='isolation_beta' else ['version 9','offline export','version 3','saved filters','campaign']
            check(not any(t in content.lower() for t in forbidden),'No foreign initiative or unassigned factual content',record['assertions'])
        if c['name']=='assignment_only_one_item':
            check(len(s['work'])==2,'Boundary scenario really contains two actual planned work items',record['assertions'])
        if c['name']=='scope_exclusions':
            out=' '.join(s['scope']['out']).lower()
            check('worker' in out and ('campaign' in out or 'marketing' in out),'Orchestrator explicitly excludes optional scope expansion',record['assertions'])
        record['pass']=True
    except Exception as e:
        record['error']=type(e).__name__+': '+str(e)
    (OUT/(c['name']+'.json')).write_text(json.dumps(record,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'name':c['name'],'pass':record['pass'],'statuses':[r.get('parsed',{}).get({'governor':'decision','orchestrator':'orchestration_status','owner':'owner_status'}[r['stage']]) for r in record['stages']],'error':record.get('error') }),flush=True)
    return record

def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--cases',nargs='*'); args=parser.parse_args()
    cfg=load_config_readonly(); model=cfg['model']['default']; route=resolve_runtime_provider(requested=cfg['model']['provider'],target_model=model)
    try:
        yaml.safe_load('duplicate: 1\nduplicate: 2\n')
    except Exception:
        pass
    else:
        raise AssertionError('YAML parser accepted duplicate keys')
    meta={'timestamp':datetime.datetime.now(datetime.timezone.utc).isoformat(),'repository':str(ROOT),'starting_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'branch':subprocess.check_output(['git','branch','--show-current'],cwd=ROOT,text=True).strip(),'model':model,'provider':route.get('provider'),'source':str(Path(__file__)),'prompt_hashes':{k:hashlib.sha256((ROOT/v).read_text(encoding='utf-8').encode()).hexdigest() for k,v in PROMPTS.items()},'native_isolation':ISOLATION,'parser':'hermes_yaml safe_load (duplicate keys rejected)'}
    (OUT/'metadata.json').write_text(json.dumps(meta,indent=2),encoding='utf-8')
    selected=[c for c in scenarios() if not args.cases or c['name'] in args.cases]
    results=[run_case(c,route,model) for c in selected]
    print(json.dumps({'scenarios':len(results),'passed':sum(r['pass'] for r in results),'failed':[r['name'] for r in results if not r['pass']]}),flush=True)
    return 0 if all(r['pass'] for r in results) else 1
if __name__=='__main__':
    raise SystemExit(main())
